"""Standalone offline frame inspector for real recorded native transitions."""
import json
from pathlib import Path

def write(path,metadata,frames):
    data=json.dumps({'metadata':metadata,'frames':list(frames)},allow_nan=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e')
    template=r'''<!doctype html><html><head><meta charset="utf-8"><title>DuelForge frame inspector</title><style>
body{margin:0;background:#10141e;color:#edf1fa;font:15px system-ui}main{max-width:1300px;margin:auto;padding:22px}h1{font-size:24px;margin:0 0 8px}.muted{color:#9caaca}section{display:grid;grid-template-columns:1.2fr 1fr;gap:20px;margin-top:20px}.box{background:#1b2232;padding:16px;border-radius:12px}canvas{width:100%;background:#131a29;border-radius:8px}button{padding:8px 16px;background:#4068ce;color:white;border:0;border-radius:6px;cursor:pointer}input{width:78%}pre{white-space:pre-wrap;font:13px ui-monospace;line-height:1.6}.blue{color:#6db8ff}.orange{color:#ffb36d}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid #39445b;padding:7px}.controls{display:flex;gap:16px;align-items:center;margin:12px 0}@media(max-width:800px){section{grid-template-columns:1fr}}
</style></head><body><main><h1>DuelForge · recorded decision inspector</h1><div class="muted" id="meta"></div><div class="controls"><button id="play">Play</button><input id="frame" type="range" min="0" value="0"><span id="time"></span></div><section><div class="box"><canvas id="field" width="640" height="720"></canvas><p><span class="blue">Blue: learner</span> · <span class="orange">Orange: frozen opponent</span></p><div class="muted">Top-down diagnostic of actual simulated poses. Arrows show velocity. This view is separate from the RocketSimVis 3D window.</div></div><div class="box"><h3 id="score"></h3><table><thead><tr><th>Reward this decision</th><th>Blue</th><th>Orange</th></tr></thead><tbody id="rewards"></tbody></table><pre id="state"></pre><h3>Blue policy: top five choices</h3><pre id="policy"></pre><div class="muted">Action probabilities and value estimates describe model outputs; they do not establish strategic intent.</div><canvas id="timeline" width="620" height="160"></canvas><p class="muted">Blue reward per transition, capped visually at ±0.1; goal spikes marked.</p></div></section></main><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.querySelector('#data').textContent),F=D.frames,S=document.querySelector('#frame'),cv=document.querySelector('#field'),ctx=cv.getContext('2d'),tl=document.querySelector('#timeline'),tx=tl.getContext('2d');S.max=F.length-1;let running=false,last=0;
document.querySelector('#meta').textContent=D.metadata.learning_transitions.toLocaleString()+' learner transitions · opponent: '+D.metadata.opponent+' · model '+D.metadata.model_sha256.slice(0,12)+' · '+F.length+' retained frames';
const xy=(x,y)=>[320+x*.06,360-y*.06];
function line(a,b,col,w=2){ctx.strokeStyle=col;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}
function circle(x,y,r,col){ctx.fillStyle=col;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function update(){const index=+S.value,r=F[index],w=r.world;ctx.clearRect(0,0,640,720);ctx.strokeStyle='#53617e';ctx.lineWidth=2;ctx.strokeRect(...xy(-4096,5120),8192*.06,10240*.06);line(xy(-4096,0),xy(4096,0),'#53617e');ctx.strokeStyle='#53617e';ctx.beginPath();ctx.arc(320,360,58,0,Math.PI*2);ctx.stroke();line(xy(-892,-5120),xy(892,-5120),'#6db8ff',9);line(xy(-892,5120),xy(892,5120),'#ffb36d',9);
ctx.globalAlpha=.3;for(let j=Math.max(1,index-90);j<=index;j++){if(F[j-1].reset)continue;for(let a=0;a<3;a++)line(xy(F[j-1].world[a][0],F[j-1].world[a][1]),xy(F[j].world[a][0],F[j].world[a][1]),a===0?'#f6e8aa':a===1?'#6db8ff':'#ffb36d',1)}ctx.globalAlpha=1;for(let a=1;a<3;a++){const p=w[a],color=a===1?'#6db8ff':'#ffb36d',[x,y]=xy(p[0],p[1]);ctx.save();ctx.translate(x,y);ctx.rotate(-Math.atan2(p[10],p[9]));ctx.fillStyle=color;ctx.fillRect(-9,-5,18,10);ctx.fillStyle='#10141e';ctx.fillRect(3,-4,3,8);ctx.restore();line([x,y],xy(p[0]+p[3]*.18,p[1]+p[4]*.18),color);ctx.fillStyle=color;ctx.fillText(Math.round(p[15])+' boost · z'+Math.round(p[2]),x+12,y-10)}
const b=w[0],[bx,by]=xy(b[0],b[1]);circle(bx,by,6+Math.min(10,b[2]/100),'#f6e8aa');line([bx,by],xy(b[0]+b[3]*.2,b[1]+b[4]*.2),'#f6e8aa');document.querySelector('#time').textContent=r.time.toFixed(2)+'s';document.querySelector('#score').textContent='Score '+r.score[0]+' : '+r.score[1]+(r.goal?' · GOAL '+(r.goal>0?'BLUE':'ORANGE'):'')+(r.reset?' · episode reset':'');
const tbody=document.querySelector('#rewards');tbody.replaceChildren();(r.reward_parts[0].length>3?['Goal','Potential change','Contact impulse','Approach bootstrap','Contact bootstrap','Total']:['Goal','Potential change','Contact impulse','Total']).forEach((name,j)=>{const row=document.createElement('tr');const vals=[name,...[0,1].map(a=>(j===r.reward_parts[a].length?r.reward_parts[a].reduce((x,y)=>x+y,0):r.reward_parts[a][j]).toFixed(5))];vals.forEach(v=>{const td=document.createElement('td');td.textContent=v;row.append(td)});tbody.append(row)});
const speed=p=>Math.hypot(p[3],p[4],p[5]);document.querySelector('#state').textContent='Ball speed: '+speed(b).toFixed(0)+' UU/s\nBall angular velocity: '+b.slice(6,9).map(x=>x.toFixed(2)).join(', ')+' rad/s\nBlue speed: '+speed(w[1]).toFixed(0)+' UU/s · airborne '+!(w[1][16]>.5)+'\nBlue jump/flip spent: '+!!w[1][18]+' · jump available '+!!w[1][29]+'\nChosen actions blue/orange: '+r.actions.join(' / ')+'\nTouch detected blue/orange: '+(r.touches||[]).join(' / ')+'\nPhysical ticks in transition: '+r.ticks+'\nBlue critic estimate: '+r.value_blue.toFixed(4)+(r.potential_debug?'\nEstimated interception blue/orange: '+r.potential_debug.slice(2,4).map(x=>x>D.metadata.predictive.horizon?'beyond horizon':x.toFixed(2)).join(' / ')+' s\nBlue potential before / next: '+r.potential_debug.slice(0,2).map(x=>x.toFixed(3)).join(' / ')+'\nApproximate geometry warning: '+!!r.potential_debug[5]:'');document.querySelector('#policy').textContent=r.top_actions.map(([a,p])=>'action '+String(a).padStart(2)+'   '+(100*p).toFixed(1)+'%').join('\n');
tx.clearRect(0,0,620,160);tx.strokeStyle='#47536c';tx.beginPath();tx.moveTo(0,80);tx.lineTo(620,80);tx.stroke();tx.strokeStyle='#6db8ff';tx.beginPath();F.forEach((f,i)=>{const reward=f.reward_parts[0].reduce((a,b)=>a+b,0),x=i/Math.max(1,F.length-1)*620,y=80-Math.max(-.1,Math.min(.1,reward))*650;if(i===0)tx.moveTo(x,y);else tx.lineTo(x,y)});tx.stroke();tx.strokeStyle='#fff';tx.beginPath();tx.moveTo(index/Math.max(1,F.length-1)*620,0);tx.lineTo(index/Math.max(1,F.length-1)*620,160);tx.stroke();}
S.addEventListener('input',update);document.querySelector('#play').onclick=()=>{running=!running;document.querySelector('#play').textContent=running?'Pause':'Play'};function tick(t){if(running&&t-last>66){S.value=(+S.value+1)%F.length;update();last=t}requestAnimationFrame(tick)}update();requestAnimationFrame(tick);
</script></body></html>'''
    Path(path).write_text(template.replace('__DATA__',data),encoding='utf8')
